programs.sol:
"""Approximate a message-ending and mathematical-boundary signal.

Message ends are strongly positive, weaker just after a document starts or
following a tool closure. Whitespace after familiar TeX control words gets
a smaller positive value based on the command class and token shape.
Document-initial pieces get coarse character-class offsets. Everything
else is zero except a few chat markup corrections. Lexical variation is
intentionally left unmodeled; these are approximate training averages.
"""
import re
import unicodedata

READS = ()
OPERATORS = set('partial nabla to mapsto cong sim approx equiv times cdot '
                'oplus otimes cup cap in le ge leq geq neq'.split())
FUNCTIONS = set('lim sum prod int iint sin cos tan log ln exp sqrt '
                'infty'.split())
ACCENTS = set('hat widehat bar overline tilde widetilde check dot ddot vec '
              'breve acute grave'.split())
FONTS = set('mathcal mathbb mathfrak mathrm mathbf mathsf mathtt'.split())
OLD_FONTS = set('rm bf it cal'.split())
DELIMITERS = set('langle rangle lvert rvert lVert rVert vert Vert'.split())
MARKERS = {'<|im_start|>': -0.05, '<tool_call>': -0.075,
           '</tool_call>': 0.13, '</tool_response>': -0.12,
           '</think>': 0.29}


def greek(name):
    name = name.removeprefix('var')
    try:
        unicodedata.lookup('GREEK SMALL LETTER ' + name.upper())
        return True
    except KeyError:
        return False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    initial = carry is None or carry[0] != doc
    tail = '' if initial else carry[1]
    position = 0 if initial else carry[2] + 1
    value = MARKERS.get(text, 0.0)
    if text == '<|im_end|>':
        if tail.rstrip().endswith(('</tool_call>', '</tool_response>')):
            value = 1.84 - 4.5 / (position + 2.0)
        else:
            value = 2.11 - 2.0 / (position + 1.1)
        value = max(0.29, value)
    elif initial:
        if text.startswith('<|'):
            value = -0.133
        elif text[:1].isalpha():
            value = -0.43 if text[:1].isascii() else -0.15
        elif text[:1].isspace():
            value = -0.12
        elif text[:1].isdigit():
            value = -0.09
        else:
            value = 0.0
    elif text[:1].isspace():
        command = re.search(r'\\([A-Za-z]+)$', tail)
        if command:
            name = command[1]
            if (greek(name) or name in OPERATORS or name in FUNCTIONS
                    or name in ACCENTS or name in FONTS
                    or name in OLD_FONTS or name in DELIMITERS
                    or name == 'displaystyle'):
                if '\\' in text:
                    value = 0.07
                elif text.strip().isalpha():
                    if name in ACCENTS:
                        value = 1.3
                    elif greek(name):
                        value = 1.0
                    elif name in FONTS or name in DELIMITERS:
                        value = 0.85
                    elif name in FUNCTIONS:
                        value = 0.7
                    elif name in OLD_FONTS or name == 'displaystyle':
                        value = 0.3
                    else:
                        value = 0.5
                elif not text.strip():
                    value = 0.45
                elif text.strip().startswith('}') and greek(name):
                    value = 0.6
                else:
                    value = 0.1
    return (doc, (tail + text)[-100:], position), value

programs.haiku:
"""Self-doubt / reconsideration detector (layers.1.mlp.down_proj:3841).

The component fires on the words a model uses when it doubts itself, reconsiders,
or thinks out loud ("Wait", "Hmm", "Alternatively", "maybe", "let me think"),
and on the punctuation right after such a word ("Wait,", "Hmm.", "Alternatively,").
It is strongest on "Wait" (about 2.4 on the word, about 2.7 on the comma after it).

The program is stateless: it looks at the current token and the one before it.
"""

READS = ()

# Activation on the word itself.
WORD = {
    "wait": 2.4, "hmm": 1.5, "ah": 1.0, "oh": 0.8, "hold": 1.4,
    "alternatively": 0.9, "maybe": 0.9, "perhaps": 0.85, "suppose": 0.85,
    "paradox": 0.9, "clarify": 0.8, "yeah": 0.7, "denote": 0.65, "think": 0.6,
    "imagine": 0.6, "visualize": 0.6, "differently": 0.6, "consider": 0.55,
    "let": 0.55, "follows": 0.5, "actually": 0.35,
}
# Activation on a comma, period or colon right after the word.
AFTER = {
    "wait": 2.7, "confusing": 1.6, "carefully": 1.2, "idea": 1.2, "oh": 1.1,
    "actually": 1.1, "confused": 1.0, "see": 1.0, "think": 0.9, "uh": 0.9,
    "differently": 0.9, "hmm": 0.85, "alternatively": 0.85, "maybe": 0.8,
    "check": 0.75, "approach": 0.75, "interesting": 0.7, "thought": 0.7,
    "perhaps": 0.6, "ah": 0.6, "no": 0.5, "again": 0.45, "problem": 0.4,
}
PUNCT = {",", ".", ":", ".\n\n", ":\n\n", "?", "!"}
DOT_LEADER = "·"


def key(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    k = key(s)
    if s in PUNCT and len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        return None, AFTER.get(key(prefix.token_strings[-2]), 0.0)
    if s.strip() and set(s) == {DOT_LEADER}:
        return None, 1.5
    # " let" and "Let" are the proposal; a bare "let" is code.
    if k == "let" and not (s[:1] == " " or s[:1].isupper()):
        return None, 0.0
    return None, WORD.get(k, 0.0)

"""Draft (scaled): negative on person-denoting nouns (people, roles, occupations)."""
READS = ()

PERSON_NOUNS = {
    "man", "men", "woman", "women", "person", "people", "friend", "friends",
    "general", "judge", "captain", "graduate", "scholar", "politician", "attorney",
    "attorneys", "manager", "professional", "professionals", "partner", "partners",
    "counterpart", "counterparts", "wife", "wives", "homme", "dames", "bishop",
    "bishops", "cardinal", "cardinals", "doctor", "runner", "student", "teacher",
    "worker", "workers", "member", "members", "family", "child", "children",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, (-0.2 if word in PERSON_NOUNS else 0.0)

programs.sol:
"""A sparse recognizer for conventional textual continuations.

Large positive responses mark C header guards and diff headers. Smaller
responses recognize citation, source-attribution, file-name, and chat
conventions. Page counters and accessibility links have negative responses.
Context is a rolling 240-character suffix, reset at document boundaries.
Unmatched text gets zero; other lexical responses remain unmodeled.
"""
import re

READS = ()


def response(token, before):
    # Paired source-code headers.
    if token == '#define' and re.search(r'#ifndef[^\n]*\r?\n$', before):
        return 8.0
    if token == '+++' and re.search(r'---[^\n]*\n$', before):
        return 3.8
    if token == ' b' and before.endswith('+++'):
        return 7.5
    if token == ' a' and before.endswith('---'):
        return 1.1
    if token == '_types' and before.endswith('declare(strict'):
        return 4.8
    if token == '/env' and before.endswith('#!/usr/bin'):
        return 1.6 if before == '#!/usr/bin' else 0.75
    if token == '.md' and re.search(r'(?:^|\n)README$', before):
        return 1.05
    if token == ' contributed' and before.endswith('This code is'):
        return 4.0

    # Conventional citations and section labels.
    if token in (' No', ' Nos') and re.search(r'\bPat\.$', before):
        return 1.2 if token == ' No' else 1.4
    if token == ' DESCRIPTION' and before.endswith('DETAILED'):
        return 1.8
    if token == ' from' and re.search(r'(?:^|\n)Retrieved$', before):
        return 0.8
    if (token.lower() == ' interest'
            and re.search(r'(?:^|\n)(?:#+ )?Conflicts of$', before)):
        return 3.0
    if token == ' of' and re.search(r'(?:United States|Supreme) Court$', before):
        return 0.9

    # Page-navigation boilerplate, including counters without spaces.
    if token in ('of', ' of') and re.search(r'\b[Pp]age\s+\d+$', before):
        return -5.4 if token == 'of' else -0.9
    if token == ' content' and re.search(r'Skip to(?: main)?$', before):
        return -2.0
    if token == ' question' and before.endswith('Rate this'):
        return 1.9

    # Chat-format delimiters: especially the start of the visible answer.
    if token == '<|im_start|>':
        return -0.355 if not before else -0.04
    if token == 'user' and before.endswith('<|im_start|>'):
        return 0.05
    if token == '\n\n' and before.endswith('</think>'):
        return 0.17
    if token == '\n\n' and before.endswith('<think>'):
        return 0.10
    if token == '<tool_response>':
        return 0.10
    if token == '<|im_end|>' and before.endswith('</tool_response>'):
        return -0.08
    if token == '</think>':
        return 0.08
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, before)
    return (doc, (before + token)[-240:]), value

programs.haiku:
"""Katakana loanword fragments: strongly negative on the short katakana pieces that start a
foreign word, weaker on the pieces that continue it, and on undecodable bytes in katakana text;
plus the 'Title:' header that opens a document."""

READS = ()

# Marks that are not a word's first kana: the long-vowel mark and the middle dot.
NON_INITIAL = set("ー・")


def _is_kata(s):
    return len(s) > 0 and all(0x30A0 <= ord(c) <= 0x30FF or 0xFF65 <= ord(c) <= 0xFF9F for c in s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    n = len(prefix)
    same_doc = n > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    doc_start = n < 3 or prefix.document_ids[-3] != prefix.document_ids[-2]
    if s == ":" and prev == "Title" and doc_start:
        return None, -20.8
    if _is_kata(s):
        first = not _is_kata(prev)
        if len(s) == 1 and s in NON_INITIAL:
            return None, (-0.5 if first else -1.0)
        if len(s) == 1:
            return None, (-3.5 if first else -1.1)
        return None, (-1.6 if first else -0.66)
    if "�" in s:
        # undecodable byte: is katakana being written nearby?
        text = prefix.text_prefixes[-1][-12:]
        katakana_nearby = any(_is_kata(c) for c in text[-6:])
        if katakana_nearby:
            return None, (-0.9 if "�" in prev else -0.45)
        return None, (-0.2 if "�" in prev else -0.1)
    return None, 0.0

programs.sol:
"""Approximate a Markdown-formatting boundary detector.

Tight closing backticks and paired emphasis marks get large positive values;
space-prefixed openings are much weaker. Bare unpaired ** after a word or
number gets a negative value, as in exponentiation or pointer syntax.
Single-star and underscore emphasis is strongest around word-like spans.
Headings, doubled table bars, nonbreaking spaces, and document-initial marks
have separate rules. Keep only 600 characters of the current line and reset
at document boundaries. Lexical fluctuations and exact magnitudes are omitted.
"""
import re

READS = ()


def opening(line, marker):
    """A matching opener at a word boundary, with no intervening marker."""
    q = re.escape(marker)
    return re.search(
        r'(?:^|[\s(\[{])' + q + r'([^' + re.escape(marker[0]) + r'\n]{1,220})$',
        line,
    )


def estimate(s, line, first):
    p = line[-1:]
    word = p.isalnum()
    tight = bool(p and not p.isspace())
    if s and s.isspace() and '\xa0' in s:
        return 0.15
    if s.strip() and set(s.strip()) == {'#'}:
        if len(s.strip()) > 1:
            return -1.1 if first else 0.7 if not line.strip() else 0.29
        return 0.0
    if s == '||':
        return 2.2 if line.lstrip().startswith('|') else 0.24
    if '`' in s and len(s) < 12:
        if s.startswith((' ', '\t')):
            return 0.08
        if s == '``':
            return 0.63 if word else -0.33 if p.isspace() else 0.05
        if s == '```' or line.endswith('`'):
            return 0.05
        if s == '`':
            if not p or first:
                return 0.12
            if not tight:
                return 0.42
            code = re.search(r'(?<!`)`([^`\n]{1,220})$', line)
            return (1.5 if len(code[1]) < 21 else 1.22) if code else 1.04
        if s.endswith('`'):
            if s.startswith(('"', "'")):
                return 2.47
            if s.startswith((')', '}', ']', '>')) or s == '()`':
                return 1.26
            return 0.32
        if s.startswith('`'):
            return 0.31 if word else 0.58
        return 0.09
    if s in ('*', '**', '_', '__'):
        if first:
            return {'*': 0.87, '**': -2.77, '_': -0.23, '__': -0.67}[s]
        match = opening(line, s)
        if match and tight:
            if s in ('*', '_'):
                text = match[1]
                words = any(c.isalpha() for c in text) and all(
                    c.isalnum() or c in " .,'’-" for c in text
                )
                if s == '*':
                    return 3.44 if words else 0.39
                return 2.58 if words else -0.16
            return 2.1 if s == '**' else 1.1
        if s in ('_', '__'):
            return -0.095
        if not tight:
            return -0.14 if s == '*' else 0.22
        if word:
            return -0.22 if s == '*' else -1.23
        return 0.17 if s == '*' else -0.15
    if '*' in s and len(s) < 8:
        if s.startswith(' '):
            return 0.07
        if s == ':**':
            return 1.47
        if opening(line, '*') or opening(line, '**'):
            if not any(c.isalnum() for c in s):
                return 0.32 if s.startswith('**:') else 0.71
        return 0.017
    return 0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    line = '' if first else carry[1]
    s = prefix.token_strings[-1]
    value = estimate(s, line, first)
    line = (line + s).rsplit('\n', 1)[-1][-600:]
    return (doc, line), value

"""Sparse continuation cues, with zero output for unrecognized contexts.

Negative cues mark dates, ordinal/ordering phrases, spatial labels and CSS
lengths. Positive cues mark module exports, relative imports and file constants.
Line-leading declarations are stronger after an import in the same document.
Keep only a short text suffix, the previous token and document-local flags.
"""
import calendar
import re

READS = ()
MONTHS = {s.lower() for s in calendar.month_name if s}
SHORT_MONTHS = {s.lower() for s in calendar.month_abbr if s}
ORDERS = {'first', 'last', 'next', 'previous', 'second', 'third'}
QUANTIFIERS = {'all', 'every', 'any', 'each'}
SUPERLATIVES = {'best', 'worst', 'most', 'least', 'minimum', 'maximum',
                'minimal', 'maximal', 'smallest', 'largest', 'highest', 'lowest',
                'widest', 'fullest', 'earliest', 'latest'}
ORDER_NOUNS = {'name', 'day', 'time', 'page', 'post', 'hand', 'resort',
               'seen', 'known', 'but', 'off', 'of', 'available'}


def classify(carry, token, doc):
    if carry is None or carry[0] != doc:
        old, prev, count, imported = '', '', 0, 0
    else:
        _, old, prev, count, imported = carry
    current = token.strip()
    word, before = current.lower(), prev.strip().lower()
    value = 0.0
    line_start = count == 0 or re.search(r'\n[ \t]*$', old)

    # Module interfaces and source-code declarations.
    if current == 'import' and count == 0:
        value = -1.81
    elif token == ':' and count == 1 and before == 'title':
        value = -4.29
    elif current == '.exports' and before == 'module':
        value = 4.56
    elif before == '.exports' and current == '=':
        value = 3.56
    elif before == 'export' and current in {'default', 'const', 'function'}:
        inline = prev != prev.lstrip()
        if current == 'default':
            value = 2.65 if inline else 7.3
        else:
            value = 2.61 if inline else 4.31
    elif before == 'default' and current in {'function', 'class'} and re.search(
            r'export\s+default$', old):
        value = 3.86
    elif re.match(r'''^[\s('\"]*\.\.?/''', token):
        if before in {'require', '.resolve'}:
            value = 2.82
        elif before in {'from', 'import'}:
            value = 0.22 if '../' in token else 3.92
    elif (current in {'const', 'function', 'export'} and
          token == token.lstrip() and line_start):
        if current == 'const':
            value = 6.14 if imported else 1.18
        elif current == 'export':
            value = 2.45 if imported else 0.78
        else:
            value = 0.0 if imported else 0.49
    elif current in {'dirname', 'filename', 'DIR', 'FILE'} and prev.endswith('__'):
        value = 5.47
    elif current == 'name' and prev.endswith('__'):
        value = 0.85
    elif current == 'solid' and before == 'px':
        value = -7.22
    elif current == 'Anchor' and prev.endswith(('.left', '.right', '.top', '.bottom')):
        value = -5.59

    # Quantified possibilities and conventional ordering phrases.
    elif word == 'possible':
        if (before in QUANTIFIERS or before in ORDERS or
                re.search(r'\b(?:all|every|any)\s+the$', old)):
            value = -3.15
        elif before in SUPERLATIVES or (len(before) > 4 and before.endswith('est')):
            value = -3.02
    elif word == 'available' and before in ORDERS | QUANTIFIERS:
        value = -1.48
    elif token == ' ':
        if re.search(r'\d(?:st|nd|rd|th)$', old):
            value = -6.29
        elif before in MONTHS | SHORT_MONTHS:
            if re.search(r'\d(?:st|nd|rd|th)\s+\w+$', old):
                value = -1.97
            elif re.search(r'\d\s+\w+$', old):
                value = (-1.18 if before in SHORT_MONTHS
                         and before not in MONTHS else -0.69)
        elif before == 'px':
            value = -2.51
        elif before in {'page', 'slide', 'top', 'author'}:
            value = -0.78
        elif before.isdigit():
            value = -0.05
    elif before in ORDERS and word in ORDER_NOUNS:
        value = -0.6
    elif re.search(r'\d(?:st|nd|rd|th)$', old):
        if word == 'of':
            value = -3.25
        elif word in {'ed', 'edition'}:
            value = -0.94
        elif current == '-' or word in {'standards', 'grade', 'grades'}:
            value = -1.57
    elif word in {'corner', 'arrow'} and before in {
            'left', 'right', 'upper', 'lower', 'top', 'bottom'}:
        value = -2.13
    elif current == '角' and prev.endswith(('左上', '左下', '右上', '右下')):
        value = -2.13

    if current == 'import' and line_start:
        imported = 1
    return (doc, (old + token)[-120:], token, count + 1, imported), value


def step(carry, prefix, upstream):
    return classify(carry, prefix.token_strings[-1], prefix.document_ids[-1])

"""Approximate a number-formatting response with short prefix rules.

Completing a three-digit group gives a negative pulse, especially after a
comma and on round thousands. Some likely list/decimal contexts weaken it.
Numeric scale words and the Chinese tenths suffix respond after numerals;
closing diff-hunk delimiters have a separate negative response. Otherwise
predict zero, apart from a document-start bias, an initial Title: label,
and middle-dot leaders. Ordinary lexical variation is not reconstructed.
"""
import re

READS = ()
SCALES = {'thousand', 'million', 'billion', 'trillion', 'mil', 'bn'}
EAST_ASIAN_SCALES = {'万', '萬', '亿', '億', '만'}
GROUP = re.compile(r'(\d+)([,，.． \u00a0])(\d{2})$')


def grouped_digit(previous, digit):
    match = GROUP.search(previous)
    if not match:
        return 0.0
    left, separator, last_two = match.groups()
    before = previous[:match.start()]
    round_thousand = int(last_two + digit) == 0
    single_zero = len(left) == 1 and int(left) == 0

    if separator in ',，':
        # Fractional parts and badly sized earlier groups suggest a list,
        # rather than one number with thousands separators.
        if single_zero:
            return -0.25
        if len(left) > 3:
            return -0.6
        if before.endswith(('.', '．')):
            return -0.25
        if before.endswith((',', '，')) and len(left) != 3:
            return -0.25
        return -1.38 if round_thousand else -1.18
    if single_zero or len(left) > 3:
        return 0.0
    if separator in '.．':
        return -0.42 if round_thousand else -0.015
    if separator == '\u00a0':
        return -0.8 if round_thousand else -0.43
    return -0.7 if round_thousand else -0.065


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower().removesuffix('s')
    value = 0.18 if position == 0 else 0.0

    if len(token) == 1 and token.isdecimal():
        value = grouped_digit(previous, token)
    elif word in SCALES and previous and previous[-1].isdecimal():
        value = -0.45
    elif (word in EAST_ASIAN_SCALES and previous
          and previous[-1].isdecimal()):
        value = -0.3
    elif token == '成' and previous and previous[-1].isnumeric():
        value = -1.0
    elif token == '%' and re.search(r'\d,\d{1,2}$', previous):
        value = -0.2
    elif token == ' @@':
        value = -0.8
    elif len(token) >= 2 and not token.strip('·'):
        value = 1.2
    elif position == 1 and previous == 'Title' and token == ':':
        value = -6.44

    return (doc, (previous + token)[-40:], position + 1), value

"""Partial foreign-nationality detector, chiefly for Chinese text.

The strongest training examples finish country shorthands or national-style
words. Dictionary country names get a smaller positive response; direct names
of China, Taiwan, Hong Kong and Macao are excluded. Additional rules cover
state suffixes, foreign communist parties, repeated middle dots (negative),
and numbered episode endings (negative). Twelve prior characters provide
word-completion context and reset at document boundaries. The many other
lexical/context-dependent responses are intentionally left unmodeled.
"""
from functools import lru_cache
import re
import regex
import cedict
import pycountry

READS = ()
COUNTRIES = set()
for country in pycountry.countries:
    for field in ('name', 'common_name', 'official_name'):
        name = getattr(country, field, '')
        if name:
            COUNTRIES.add(name.lower())
DOMESTIC = {'china', 'prc', "people's republic of china"}
REGIONS = {'europe', 'european union', 'africa', 'oceania', 'the americas',
           'united nations', 'korea'}

# Common short names not used as ISO's principal English country name.
COUNTRIES.update({'russia', 'britain', 'england', 'holland', 'laos', 'usa', 'us', 'uk'})
DOMESTIC.update({'taiwan', 'hong kong', 'macao'})

@lru_cache(None)
def foreign_name(name):
    name = name.strip().lower()
    return name not in DOMESTIC and (name in COUNTRIES or name in REGIONS)

@lru_cache(None)
def meanings(text):
    return cedict.glosses(text)

@lru_cache(None)
def foreign_word(text):
    for gloss in meanings(text):
        gloss = re.sub(r'^\([^)]*\)\s*', '', gloss)
        gloss = re.sub(r'^abbr\. for ', '', gloss)
        head = re.split(r'[;,(]|[^\x00-\x7f]', gloss)[0].strip()
        if head[:1].isupper() and foreign_name(head):
            return True
    return False

@lru_cache(None)
def abbreviation(ch):
    return len(ch) == 1 and any('abbr.' in g for g in meanings(ch)) and foreign_word(ch)

@lru_cache(None)
def token_signal(token):
    s = token.strip()
    han = bool(regex.search(r'\p{Script=Han}', s))
    country = han and len(s) > 1 and foreign_word(s)
    # A leading preposition may share the country's token.
    if not country and len(s) > 2 and regex.fullmatch(r'\p{Script=Han}+', s):
        country = any(foreign_word(s[n:]) for n in range(1, len(s) - 1))
    value = 0.0015 + 1.9 * country
    if s.isascii() and s.isalpha() and foreign_name(s):
        if s.lower() not in {'us', 'uk'} or s.isupper():
            value += 0.04
    if s == '州':
        value += 1.44
    if len(s) >= 2 and set(s) == {'·'}:
        value -= 1.51
    return value, country, han


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.strip()
    value, country, han = token_signal(token)
    last = before[-1:]
    completed_shorthand = False
    if s and han and abbreviation(last):
        if s[0] in '国國' and foreign_word(last + s[0]):
            completed_shorthand = True
            value += 6.5
        elif s[0] in '式系裔':
            value += 5.1
        elif s.startswith('共'):
            value += 7.8 if s == '共' else 3.9
    elif s.startswith(('共产党', '共產黨')) and foreign_word(before[-2:]):
        value += 3.9
    if s == '集' and before[-1:].isdigit():
        value -= 1.37
    split_name = s in {'国', '國'} and before.endswith('共和')
    if not country and not completed_shorthand and 0 < len(s) <= 4 and han:
        split_name = split_name or any(
            foreign_word(before[-n:] + s)
            for n in range(1, min(4, len(before)) + 1))
    if split_name:
        value += 1.09
    return (doc, (before + token)[-12:]), float(value)

"""Approximate a sparse signal for comparative and relational collocations.

Strong positive examples include 'compared (to)', 'rather (than)',
'with respect (to)' and 'on top (of)'. Some adverbial idioms, such as
'as before', have negative signals. Fixed phrase weights are supplemented
by simple verb-context and comparison-word heuristics. A fraction of the
signal continues onto the following preposition.

This is a small phrase lexicon, not a full grammar. It includes temporal
phrases, several French/Russian equivalents (including visible Russian
word stems), and a reference-markup opener. Background and most code
fragment responses are left at zero. Recent text resets at document edges.
"""
import re

READS = ()

# Final words of familiar two-word constructions, with their signal sizes.
PHRASES = {
    'as': {
        'opposed': 7.4, 'compared': 9.3, 'shown': 1.6, 'seen': 3.2,
        'demonstrated': 3.1, 'observed': 3.4, 'defined': 2.0,
        'described': 1.1, 'expected': .8, 'required': 1.5,
        'previously': 2.2, 'implied': 1.5, 'depicted': 1.4,
        'long': 2.0, 'soon': 2.0, 'fast': 2.3, 'quickly': 2.7,
        'far': 1.0, 'can': 1.6,
        'assessed': 3.5, 'measured': 3.4, 'revealed': 2.6,
        'distinguished': 3.6, 'best': 3.0,
        'before': -3.0, 'ever': -5.6, 'always': -6.0,
        'in': -2.8, 'such': -1.9, 'if': -1.2, 'per': -1.9,
        'above': -1.5, 'with': -.8,
    },
    'in': {
        'comparison': 6.7, 'contrast': 4.6, 'relation': 4.6,
        'front': 2.9, 'recent': 3.9, 'terms': 1.1,
        'response': 1.8, 'spite': 3.3, 'exchange': 2.1,
        'vivo': 1.3, 'conjunction': 1.3, 'addition': .9,
        'excess': 1.6, 'opposition': 2.3, 'between': .8,
        'practice': 1.5, 'favor': 1.1, 'hand': -2.1,
    },
    'with': {'respect': 4.1, 'regard': 2.6},
    'on': {'top': 5.8, 'hand': -5.2, 'behalf': 2.1,
           'opposite': 3.5, 'average': 2.2},
    'at': {'night': 3.7, 'first': 1.2, 'best': 2.8, 'hand': -2.4},
    'by': {'comparison': 2.5, 'contrast': 2.8},
    'over': {'time': 1.3, 'night': 5.0},
    'than': {'ever': -2.1, 'before': -1.8},
    'par': {'rapport': 9.7},
    # Russian: relative to, compared with, according to; in contrast/dependence.
    'по': {'отношению': 12.3, 'сравнению': 8.9, 'мнению': 4.3,
           'отнош': 6.4, 'сравн': 4.7},
    'в': {'зависимости': 1.9, 'отличие': 2.3, 'отлич': 6.0},
}

AUXILIARIES = {
    'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
}
SUBJECTS = {'i', 'we', 'you', 'he', 'she', 'they', 'it'}
ADVERBS = {'often', 'readily', 'also', 'then', 'further', 'broadly'}


COMPARATIVES = set('more less better worse higher lower larger smaller greater '
                   'fewer faster slower longer shorter cheaper stronger weaker'.split())


def last_word(text):
    """A word at the end, including one assembled from several subword tokens."""
    match = re.search(r'\w+$', text)
    return match.group() if match else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0)
    _, tail, last_value = carry
    raw = prefix.token_strings[-1]
    tail = (tail + raw)[-160:]
    if not raw or not raw[-1].isalpha():
        return (doc, tail, 0.0), 0.0
    parts = tail.rsplit(None, 2)
    original = last_word(parts[-1])
    word = original.lower()
    previous = last_word(parts[-2]).lower() if len(parts) > 1 else ''
    before_previous = last_word(parts[-3]).lower() if len(parts) > 2 else ''
    if original.isupper() and len(original) > 1:
        return (doc, tail, 0.0), 0.0
    verb_context = (previous in AUXILIARIES | SUBJECTS or
                   previous in ADVERBS)
    value = 0.0

    if word == 'compared':
        value = 7.8
        if COMPARATIVES.intersection(re.findall(r'\w+', tail.lower())[:-1]):
            value += 2.4
        if verb_context:
            value = .2
        elif previous in {'have', 'has', 'had', 'and', 'if'}:
            value = 2.0
        elif previous == 'when':
            value = 5.8
    elif word in {'followed', 'contrasted'}:
        value = 2.8
        if verb_context or previous in {'have', 'has', 'had', 'and'}:
            value = 0.0
    elif word == 'rather':
        value = 2.9 if previous not in {'but', 'or'} else 0.0
        if previous in AUXILIARIES | {'a', 'the'}:
            value = .8
    elif word == 'instead':
        value = 1.8
        if previous in AUXILIARIES | {'but', 'and', 'have', 'can'}:
            value = .4
        elif previous == 'used':
            value = 3.1
        elif raw.strip() == 'Instead':
            value = 1.0
    elif word == 'relative':
        value = 1.4 if previous in {'a', 'the', 'its', 'their', 'his'} else 2.5
    elif word in {'divided', 'combined'}:
        value = 0.0 if verb_context else 1.2
    elif word == 'overnight':
        value = 1.8
    elif word in {'versus', 'conversely', 'inversely'}:
        value = {'versus': 1.1, 'conversely': 3.3, 'inversely': 1.2}[word]
    elif word == 'over':
        value = 3.5 if previous.startswith('improv') else .33

    if previous == 'as' and len(word) > 4 and word.endswith('ed'):
        value = 1.5
    value = PHRASES.get(previous, {}).get(word, value)
    if previous == 'in' and word == 'addition' and original == 'addition':
        value = .9 if tail.endswith('in addition') else .25
    if word in {'to', 'with'} and previous in {'compared', 'comparison'}:
        value = (.6 if word == 'to' else .7) * max(last_value, 0.0)
    elif word == 'to' and previous == 'relative':
        value = .6 if before_previous in AUXILIARIES else 3.2
    elif word == 'to' and previous == 'opposed':
        value = .5 * max(last_value, 0.0)
    elif word == 'by' and previous == 'followed':
        value = .5 * max(last_value, 0.0)
    elif word == 'to' and previous == 'contrast':
        value = 1.4
    elif word == 'of' and previous == 'top':
        value = .13 * max(last_value, 0.0)
    elif word == 'ref' and tail.endswith('){ref'):
        value = 1.7

    return (doc, tail, value), value

"""Approximate printed-whitespace and modern-year-prefix responses.

Horizontal spacing is strongly negative after printed line numbers or escaped
newlines, and weaker after ordinary newlines or inside a line.  The second digit
of a number beginning 19 or 20 is another negative cue, especially after spaces
or a spaced parenthesis.  Chinese 一九 is similar.  Initial horizontal blanks
instead receive a positive value.  These are rough response levels, not exact
reconstructions; state resets at each document boundary.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, tail, line, number, boundary, previous = 0, '', '', '', '', ''
    else:
        _, pos, tail, line, number, boundary, previous = carry
    s = prefix.token_strings[-1]
    value = 0.0
    numbered = bool(re.fullmatch(r' *[0-9]+:?[\t ]*', line))
    horizontal = bool(s) and all(c in ' \t\xa0' for c in s)

    if horizontal:
        n = len(s)
        if pos == 0 and '\xa0' not in s:
            if set(s) == {'\t'}:
                value = 2.55
            elif '\t' in s:
                value = 2.1
            else:
                value = 2.4 if n <= 8 else 1.8
        elif tail.endswith('\\n'):
            value = -1.3 if n <= 4 else -1.44 if n <= 17 else -1.14
            if tail.endswith('\\\\n'):
                value *= 0.75
        elif numbered and '\t' in s:
            if s.endswith(' '):
                value = -1.3 if s.count(' ') <= 2 else -1.62
            else:
                value = -1.05 if n == 1 else -1.55
        elif '\xa0' in s:
            value = -0.95 if n >= 3 else 0.0
        elif '\t' in s:
            value = 0.07 if not line.strip() else -0.3
        elif n >= 3 and line.strip():
            value = -0.8 if line.strip() in {'+', '-', '//'} else -0.5
        elif tail.endswith('\n'):
            value = -0.23 if n == 1 else -0.03
    elif s.startswith('\t') and numbered and s.lstrip('\t').isalpha():
        word = s.lstrip('\t')
        value = -0.65 if word in {'from', 'import', 'export'} else -0.2

    if (s == '0' and number == '2') or (s == '9' and number == '1'):
        if boundary.isspace():
            value = -0.57 if s == '0' else -0.74
        elif boundary.startswith(' ') and boundary.rstrip().endswith('('):
            value = -0.79 if s == '0' else -0.92
        elif boundary.endswith('/'):
            value = -0.39
        else:
            value = -0.2
    elif s == '九' and tail.endswith('一'):
        value = -1.7

    tail = (tail + s)[-100:]
    line = (line + s).rsplit('\n', 1)[-1][-100:]
    if s and s.isascii() and s.isdigit():
        if not number:
            boundary = previous
        number = (number + s)[-10:]
    else:
        match = re.search(r'[0-9]+$', s)
        number = match.group() if match else ''
    return (doc, pos + 1, tail, line, number, boundary, s), value

programs.haiku:
"""Document-opening token classes.

This component is silent everywhere except the first token of a document, where it
writes a large, token-specific value (typically -18 to +17). The value depends only on
that token, because at the first position attention sees nothing but the token itself.
The program sorts opening tokens into a few classes and gives each class its average:
  - capitalised words that open a sentence (The, In, After, Next, ...): strongly negative
  - lowercase function words mid-sentence (the, of, is, was, ...): negative
  - technical / web / commerce words (API, file, user, repository, ...): positive
  - digits, special tokens, whitespace, and everything else: small values
Every other position predicts 0.
"""

READS = ()

TECH_WORDS = {
    "api", "json", "file", "files", "user", "users", "project", "repository", "response",
    "module", "package", "server", "sqlite", "adapter", "bucket", "hardware", "software",
    "computer", "online", "web", "customer", "merchants", "service", "shipping", "vendor",
    "bitcoin", "broadband", "remote", "reliable", "instant", "your", "you", "url", "http",
    "config", "test", "manage", "download", "account", "email", "data", "code", "python",
    "oracle", "route", "reservation", "library", "developer", "install", "script",
}
FUNCTION_WORDS = {
    "the", "a", "an", "of", "in", "on", "at", "to", "is", "was", "and", "or", "with",
    "that", "it", "as", "by", "for", "be", "are", "were", "from", "into", "not", "so",
    "if", "but", "this", "there", "which",
}
CLASS_VALUE = {
    "tech": 6.0, "function": -4.0, "capital": -5.0, "special": -2.5,
    "digit": -1.7, "space": -0.7, "other": -1.9,
}


def token_class(s):
    core = s.strip()
    if s.startswith("<|"):
        return "special"
    if core == "":
        return "space"
    if core.isdigit():
        return "digit"
    if core.lower() in TECH_WORDS:
        return "tech"
    if core.lower() in FUNCTION_WORDS:
        return "function"
    if core[:1].isupper() and core.isalpha():
        return "capital"
    return "other"


def step(carry, prefix, upstream):
    t = len(prefix.token_ids) - 1
    starts_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_doc:
        return None, 0.0
    return None, CLASS_VALUE[token_class(prefix.token_strings[-1])]

programs.sol:
"""A punctuation feature: colons dominate, with smaller inline separator signals.

Training examples distinguish prose semicolons from programming syntax, and
periods after initials from numeric periods. Newlines generally weaken marks.
The rules also cover command-option dashes, repeated middle-dot dividers and
large responses to document-opening title labels. Words default to zero;
lexical and finer contextual variation is intentionally not modeled.
Only the last 100 characters and the previous token are retained per document.
"""
import re
import unicodedata

READS = ()
COMMANDS = set('cat head tail grep rg find sed awk git curl python pip cargo '
               'npm node pytest diff ls rm mkdir chmod tar docker'.split())
CODE_WORDS = re.compile(r'\b(return|break|continue|true|false|null|const)\b')


def activation(s, previous, position, recent):
    token = unicodedata.normalize('NFKC', s)
    mark = token.strip()
    prev = previous.strip()
    nl = '\n' in token or '\r' in token
    if mark == ':' and position == 1 and recent == 'Title':
        return 19.48
    if mark == ':' and position == 2 and recent == '---\ntitle':
        return 5.00
    if (mark and set(mark) == {'·'} and len(mark) >= 2
            and (position == 0 or previous.strip() == mark)):
        return -2.50
    if not mark or any(c.isalnum() for c in mark):
        return 0.0
    if '=' in mark:  # Assignment/comparison operators are not clause marks.
        return 0.25 if ':' in mark else 0.0
    if ':' in mark and '/' not in mark:
        if position == 0:
            return -0.33
        if mark.count(':') > 1:
            return 0.39
        if mark.endswith(('"', '“')):
            return 0.30
        if mark.lstrip('\\').startswith(('"', "'")):
            return 0.40 if '\\' in mark else 0.57
        if '*' in mark:
            return 0.75
        if nl:
            if mark.startswith((')', ']')):
                return 0.83 if token.count('\n') > 1 else 0.37
            lines = token.count('\n')
            return 0.95 if lines == 2 else (0.51 if lines > 2 else 0.82)
        if token.startswith(' '):
            return 0.99
        return 1.12 if any(c in recent for c in '{}=') else 1.26
    if ';' in mark:
        if position == 0:
            return -0.49
        if nl:
            return 0.02
        code = (any(c in recent for c in '{}=') or CODE_WORDS.search(recent)
                or re.search(r'&\w+$', recent)
                or re.search(r'[-\w]+:\s*[^;{}]*$', recent))
        return 0.21 if code else 0.98
    if '?' in mark:
        return 0.34 if nl else (0.89 if mark == '?' else 0.60)
    if '!' in mark:
        return 0.04 if nl else (0.52 if mark == '!' else 0.20)
    if mark.count('.') > 1:
        return 0.09 if nl else (0.65 if not mark.strip('.') else 0.30)
    if '.' in mark:
        if nl:
            return -0.04
        if token.startswith(' '):
            return 0.0
        if mark != '.':
            return 0.25 if mark.endswith('.') else 0.03
        if prev.isupper():
            return 0.54
        return 0.19 if prev[-1:].isdigit() else 0.31
    if '。' in mark:
        return -0.08 if nl else 0.14
    if mark in ('-', '--'):
        return 1.20 if token.startswith(' ') and prev in COMMANDS else -0.02
    if ',' in mark or '、' in mark:
        return -0.03
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, '')
    _, previous, position, recent = carry
    s = prefix.token_strings[-1]
    value = activation(s, previous, position, recent)
    return (doc, s, position + 1, (recent + s)[-100:]), value

programs.haiku:
"""Punctuation detector for one residual-stream direction.

The component fires on punctuation marks that introduce or split a clause: a colon is
strongest, then a question mark, a semicolon, an ellipsis or exclamation mark, and a
period. A period after a capital letter (an initial, as in "John J.") or an all-caps
abbreviation fires more; a period after a digit fires less. A mark fused with a line break
(";\\n") is off. The one huge response: the colon of a "Title:" that opens a document (right
after the <|endoftext|> separator), where the component reaches about 19.
"""

READS = ()

COLONS = {":", "：", " :", "):", "]:", "**:", "():", "`:", ":\\"}
COLON_NEWLINE = {":\n", ":\n\n"}
QUOTE_COLONS = {'":', "':", "::"}
QUESTIONS = {"?", "？", " ?", "?:"}
SEMICOLONS = {";", "；", " ;", ");"}
DOTS = {"...", "…", ".."}


def period_value(prev):
    word = prev.strip()
    if word[-1:].isupper() and len(word) <= 2:
        return 0.9
    if word.isupper() and len(word) > 1:
        return 0.5
    if word[-1:].isdigit():
        return 0.2
    return 0.3


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if prefix.position == 0:
        return None, -0.2
    if tok in COLONS:
        if toks[-2] == "Title" and len(toks) > 2 and toks[-3] == "<|endoftext|>":
            value = 19.4
        else:
            value = 1.2
    elif tok in COLON_NEWLINE:
        value = 0.9
    elif tok in QUOTE_COLONS:
        value = 0.5
    elif tok in QUESTIONS:
        value = 0.9
    elif tok in SEMICOLONS:
        value = 0.7
    elif tok in DOTS:
        value = 0.6
    elif tok == "!":
        value = 0.5
    elif tok == ".":
        value = period_value(toks[-2]) if len(toks) > 1 else 0.4
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A sparse detector of formulaic openings and their continuations.

Most tokens get nearly zero. Fixed greetings, thanks, introductions, and
source-code prologues have negative responses on their continuation words.
Positive cases include chat headers, forum links, title/solution labels,
and middle-dot separators.
A small, shape-based bias approximates the first token of each document.
These rules deliberately leave ordinary lexical variation unexplained.
"""
import re
import regex

READS = ()


def opening(token):
    word = token.strip()
    if token in ('package', 'import', 'class', 'export'):
        return 1.2
    if not word:
        return 0.28
    if token.startswith(' '):
        return 0.06
    if word.isdecimal():
        return 0.13
    if word.isascii() and word.isalpha():
        if word.isupper():
            return 0.32
        return 0.45 if word[0].isupper() else 0.18
    if regex.search(r'\p{Script=Han}', word):
        return 0.31
    return 0.13 if any(c.isalpha() for c in word) else 0.27


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, recent = 0, ''
    else:
        _, age, recent = carry
    token = prefix.token_strings[-1]
    # Treat quoted source code's escaped line breaks as line breaks too.
    before = recent.replace('\\n', '\n').replace('\\t', '\t')
    value = opening(token) if age == 0 else -0.0026

    if token == '\n' and before.endswith('<|im_start|>user'):
        value = 0.0825 if age == 2 else 0.417
    elif token == ' main':
        if re.search(r'\bpackage$', before):
            value = -17.95 if age == 1 else -11.8
            if recent.endswith('\npackage') and not recent.endswith('\\npackage'):
                value = -14.8
        elif re.search(r'\b(?:func|fn|fun|def)$', before):
            numbered = re.search(r'\n *\d+\t(?:func|fn|fun|def)$', before)
            value = -0.7 if numbered else -3.1
        elif re.search(r'\bint$', before):
            value = -0.48
    elif token in (' com', ' org') and re.search(r'\bpackage$', before):
        if token == ' com':
            value = -4.95 if age == 1 else -1.25
        else:
            value = -3.75 if age == 1 else -1.3
    elif token == 'php' and age == 1 and before == '<?':
        value = -5.16
    elif token == ' std' and before.endswith(' namespace'):
        value = -1.37
    elif token == ' for':
        if re.search(r'\bThank you$', before):
            line = before[:-len('Thank you')]
            value = -5.6 if not line or line.endswith('\n') else -4.3
        elif re.search(r'\bthank you$', before):
            value = -1.7
        elif re.search(r'\b[Tt]hanks$', before):
            value = -1.15
        elif re.search(r'\b[Tt]hank(?:s| you) (?:so|very) much$', before):
            value = -0.2
    elif token == ' morning' and re.search(r'\b[Gg]ood$', before):
        value = -7.4
    elif token == ' to' and re.search(r'\b[Ww]elcome$', before):
        value = -3.5
        if before.endswith('Welcome'):
            if age == 1:
                value = -4.64
            elif re.search(r'(?:^|\n)#{1,6} Welcome$', before):
                value = -7.0
    elif token in (' name', ' Name'):
        if re.search(r'\bMy$', before):
            value = -4.5 if token == ' name' else -1.4
        elif re.search(r'\bmy$', before):
            value = -1.17
        elif re.search(r'\b[Yy]our$', before):
            value = -0.82
    elif token == ' watching' and re.search(r'\b[Tt]hank(?:s| you) for$', before):
        value = -1.78
    elif token == '好' and before.endswith('大家'):
        value = -9.9
    elif token == ' Summary' and re.search(r'(?:^|\n)#{1,6} Solution$', before):
        value = 6.14
    elif token == '0' and before.endswith('\\x'):
        value = -0.7
    elif token == 'permalink' and before.endswith('[#'):
        value = 2.02
    elif len(token) >= 2 and set(token) == {'·'}:
        value = 1.12
    elif token == ':' and age == 1 and before == 'Title':
        value = 4.47

    return (doc, age + 1, (recent + token)[-180:]), float(value)

"""Opening typography, with a positive pulse for a space followed by a period.

It also gives negative opening pulses for boundary tokens and empty comments.
Ordinary opening words are weakly negative unless very common in English.
An opening run of identical punctuation keeps its opening value. Away from
openings it is almost silent, except for title labels and forum/banner markup.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

