"""layers.1.mlp.down_proj:3886 - a 'tab-newline' detector plus a document-start rule.

What it does, in plain terms:
1. Whitespace line-ends. The component fires on a token that is only whitespace and ends in a
   newline, most strongly on a bare tab + newline ("\\t\\n", an empty line in tab-indented code
   or in a line-numbered listing): about +0.6. Other indented blank-line tokens that contain a tab
   or several spaces fire more weakly (about +0.3). Everything else in the middle of a
   document is near zero; that part of its output is token-specific noise we do not model.
2. First token of a document (the first token of a row, or the first token after a document
   break; attention cannot see anything before it). Its activation depends only on which token it
   is, so a few coarse classes are used: a lone space is high (+0.7); digits, punctuation,
   and words with no leading space are negative; words with a leading space are about zero.
"""

READS = ()


def _is_blank_line_end(token):
    return token.strip() == "" and token.endswith("\n")


def _doc_start_value(token):
    if token == " ":
        return 0.7
    if token.strip().isdigit():
        return -0.13
    if token[:1] == " " and token.strip():
        return 0.0
    if token.strip() == "":
        return -0.1
    if token[:1].isalpha():
        return -0.18
    return -0.08


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    starts_document = len(prefix.document_ids) == 1 or (
        prefix.document_ids[-1] != prefix.document_ids[-2]
    )
    if starts_document:
        return carry, _doc_start_value(token)
    if token == "\t\n":
        return carry, 0.6
    if _is_blank_line_end(token) and ("\t" in token or len(token) >= 5):
        return carry, 0.3
    return carry, 0.0

