"""Approximate a scientific-reference and identifier-markup detector.

Large values mark LaTeX reference braces, reference-type prefixes (eq, fig,
sec, etc.) and identifier colons. Smaller values cover citation markers,
Markdown anchors, reference attributes and formal LaTeX environment names.

A bounded parser keeps the last 100 characters and a short identifier span. It resets at document boundaries and ignores other activations.
The numbers are approximate strengths estimated from training examples.
"""
import re

READS = ()
REFERENCE_COMMAND = re.compile(r'\\(label|(?:eq|page|auto|C)?ref|cite[pt]?)\*?$')
ID_HEADS = {'eq', 'equ', 'fig', 'tab', 'sec', 'app', 'th', 'thm',
            'prop', 'lem', 'lemma', 'def', 'conj', 'cor', 'claim'}
ENVIRONMENTS = ('theorem', 'lemma', 'proposition', 'proof', 'corollary',
                'claim', 'definition', 'conjecture', 'table', 'subproof')
REFERENCE_WORD = re.compile(
    r'(?:fig(?:ure)?s?|eq(?:uation)?s?|tables?|sections?|theorems?|'
    r'lemmas?|propositions?|corollaries?|conjectures?|property)\.?[\s~(]*$',
    re.I)


