    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, mode, age, head = '', '', 0, ''
    else:
        _, before, mode, age, head = carry
    token = prefix.token_strings[-1]
    value = 0.0
    command = REFERENCE_COMMAND.search(before)
    opening = ''
    if token.startswith('{') and command:
        opening = 'cite' if command[1].startswith('cite') else 'id'
        value = 10.0 if opening == 'cite' else 18.5
    elif token in ('[', '\\['):
        if token == '\\[' or before.endswith('\\'):
            context = before[:-1] if token == '[' else before
            opening = 'guess'
