                opening, value = 'id', 15.5 if token == '[' else 11.0
            elif context.endswith('('):
                opening, value = 'id', 12.5
            elif context.endswith('\u00a0'):
                opening, value = 'id', 10.0
            elif token == '\\[' and re.search(r'[.}$]\n\n$', context):
                value = 6.5
    elif token.strip() == '[@':
        value = 7.5 if before.endswith('\u00a0') else 3.5
        if token.startswith(' ') and not before.rstrip().endswith((']', '],')):
            value = 5.8
        opening = 'cite'
    elif token == ' @' and before.endswith(';') and ('@' in before):
        opening, value = 'cite', 8.0
    elif token == '@' and before.endswith('['):
        opening, value = 'cite', 5.5 if before.endswith('.[') else 2.0
    elif token == '#' and before.endswith('{'):
        opening, value = 'id', 2.0 if before.endswith('){') else 5.0
    elif token == '#' and before.endswith(']('):
        opening, value = 'anchor', 1.0
    elif token == '](':
        value = 0.9
    elif before.endswith('ref-type="'):
        value = 5.3 if token == 'fig' else 3.5 if token == 'table' else 0.0
    elif token == '="' and before.endswith(('ref-type', 'data-label')):
        value = 9.5 if before.endswith('data-label') else 1.6
        if before.endswith('data-label'):
