    elif token == ':' and before.endswith('arXiv'):
        value = 5.0
    # 'guess' is an ambiguous escaped bracket; a type prefix confirms an ID.
    elif mode in ('id', 'guess'):
        word = token.lower()
        combined = head + word
        if word in ID_HEADS or combined.endswith('thm'):
            value = 12.5 if age == 0 or combined.endswith('thm') else 6.5
            if word == 'equ':
                value = 6.0
            if word == 'th':
                value = 8.5
            mode = 'id'
        elif token == ':' and mode == 'id':
            numeric = len(head) == 1 or any(c.isdigit() for c in head)
            value = 9.0 if numeric else 15.5
        elif token.startswith(':') and mode == 'id':
            value = 9.5
        elif token == '\\_' and mode == 'id':
            value = 5.0
        elif token.isalpha() and age == 0 and mode == 'id':
            value = 5.0
        if token.isalnum():
            head += word
    elif mode == 'cite' and token.startswith(':'):
        value = 5.0
    elif mode == 'anchor' and age == 0 and token.isalpha():
        value = 9.0 if token in ID_HEADS else 1.5
        if len(token) == 1 and token.islower():
            value = 4.0
    # Names of formal environments, including names split over several tokens.
    env = re.search(r'\\(begin|end)\{([a-z]*)$', before)
    if env and token.isalpha():
        name = env[2] + token
        if any(word.startswith(name) for word in ENVIRONMENTS):
            value = 5.5 if not env[2] or len(token) >= 5 else 1.0
            if env[1] == 'end':
