# Mathematica-style function call: "[" (or "[{") directly after a CamelCase or
# Wolfram built-in name such as Module[, Apply[, Verbatim[. Predicts a modest value there.
WOLFRAM_CALLS = {"Module", "Apply", "Verbatim", "Sin", "Cos", "Table", "Map", "Select"}

def _camel(s):
    if s in WOLFRAM_CALLS:
        return True
    return any(a.islower() and b.isupper() for a, b in zip(s, s[1:]))

