"""A partial model of negative responses to Indonesian word pieces.

Track the unfinished ASCII word and a decaying score of Indonesian function
words. Compare its frequency as a complete word with the frequency of its
possible completions. In Indonesian-looking text, unfinished prefixed words
receive negative values. Completing the spellings di-per-, di-ber-, mem-per-
or starting what follows them receives extra weight.

Also model a small negative opening-word baseline, a positive opening
"Title:" label, and negative repeated middle-dot separators. Reset language
state at document boundaries and end-of-text markers. Finer token-specific
variation is not modeled.
"""
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
AFFIXES = ('ber', 'ter', 'me', 'di', 'ke', 'pe', 'se')
STACKED = ('diper', 'diber', 'memper')
# 'di' is excluded as language evidence: it is also an Italian preposition.
FUNCTIONS = set('yang dan ini dari untuk dengan itu bisa aku ada tidak '
                'akan adalah dalam pada kita orang ke juga anda dia saya '
                'kamu lebih sudah mereka tapi karena atau menjadi harus '
                'seperti oleh jika hanya sebagai telah bahwa bukan masih '
                'sebuah setelah'.split())

# Maximum frequency of a dictionary word beginning with each string.
BEGINS = {}
for language in ('id', 'en'):
    table = {}
    for word in top_n_list(language, 100000):
        if word.isascii() and word.isalpha():
            frequency = zipf_frequency(word, language)
            for length in range(1, len(word) + 1):
                table.setdefault(word[:length], frequency)
    BEGINS[language] = table

@lru_cache(maxsize=100000)
def frequencies(word):
    return (zipf_frequency(word, 'id'), zipf_frequency(word, 'en'),
            BEGINS['id'].get(word, 0), BEGINS['en'].get(word, 0))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0.0)
    _, previous, context = carry
    token = prefix.token_strings[-1]
    if token == '<|endoftext|>':
        return (document, '', 0.0), 0.0
    at_start = prefix.position == 0 or (
        prefix.token_strings[-2] == '<|endoftext|>'
        or prefix.document_ids[-2] != document)
    if token == ':' and prefix.position > 0:
        if prefix.token_strings[-2] == 'Title' and (
            prefix.position == 1 or prefix.token_strings[-3] == '<|endoftext|>'):
            return (document, '', context), 7.25
    if token == '··' and (at_start or prefix.token_strings[-2] == '··'):
        return (document, '', context), -1.29
    if token and not (token[0].isascii() and token[0].isalpha()):
        if previous:
            context = .9 * context + .1 * (previous in FUNCTIONS)
        previous = ''
    word = previous
    for part in re.findall('[A-Za-z]+|[^A-Za-z]+', token):
        if part.isascii() and part.isalpha():
            word += part.lower()
        else:
            if word:
                context = .9 * context + .1 * (word in FUNCTIONS)
            word = ''
    state = (document, word[-40:], context)
    piece = token.strip().lower()
    if not (piece.isascii() and piece.isalpha()) or len(word) > 40:
        return state, 0.0
    exact_id, exact_en, begin_id, begin_en = frequencies(word)
    gap = begin_id - begin_en
    unfinished = begin_id - exact_id
    morphological = any(word.startswith(affix) and len(word) >= len(affix) + 2
                        for affix in AFFIXES)
    value = 0.0
    if context > .15:
        if unfinished > 4:
            if morphological:
                previous_id = frequencies(previous)[2]
                value = -3.80 if previous_id > 5.5 else -2.08
            else:
                value = -1.04 if gap > 1.5 else -.33
        elif morphological:
            if frequencies(previous)[3] > 0:
                value = -1.24
            else:
                piece_id, piece_en, _, _ = frequencies(piece)
                value = -.15 if piece_id - piece_en > 1 else -.67
        elif unfinished > .5:
            value = -.42 if context > .2 else -.17
        else:
            value = .11 if exact_id > 5.75 else -.03
    elif at_start:
        value = -.15
    elif gap > 3.75:
        if morphological:
            if context > .001:
                value = -2.89 if unfinished > 0 else -.66
            else:
                value = -.43 if len(previous) > 2 else .03
        elif context > .01 and exact_id <= 5.25:
            value = -.26
    # Completing a stacked prefix, then beginning its root, is a stronger event.
    if context > .001 and unfinished > 4:
        if word in STACKED:
            value = -5.5
        elif previous in STACKED:
            value = -6.5
    return state, value

"""Approximate an unspaced word/identifier continuation signal from spelling.

Space-prefixed words are near zero; unspaced word pieces are positive, with
script-specific levels. Opening/joining punctuation is positive and ordinary
closing punctuation is near zero. Initial tokens and space-prefixed closing
punctuation are suppressed. Digit runs distinguish numbers after whitespace
from identifiers and symbol-prefixed numbers. Chat boundaries have separate
values. State resets at document boundaries; no lexical lookup is used.
"""
import unicodedata

READS = ()
CLOSING = set('.,;:!?)]}，。！？、；：')
JOINING = set('_-/\\=+*^%&|@')
OPENING = set('([{')


def script(char):
    name = unicodedata.name(char, '')
    for family in ('LATIN', 'CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL'):
        if family in name:
            return family
    return 'OTHER'


def predict(text, previous, first=False, number_run=1, number_start=' '):
    if text == '<|im_end|>':
        return 2.6 if previous.endswith('.') else 3.3
    if text == '<|im_start|>':
        return 0.3 if previous.endswith('\n') else -1.8
    if text.startswith('<|') or not text:
        return 0.0
    if first:
        return -1.0
    word = text.strip()
    if not word:
        return -0.65 if text.startswith(' ') and '\n' in text else 0.02
    char = word[0]
    family = script(char)
    before = previous[-1:] or ' '
    spaced = text[0].isspace()
    if spaced:
        if char.isalpha():
            if family in ('CJK', 'HANGUL'):
                return -1.0 if family == 'CJK' else -0.8
            return -0.4 if before in '({' else -0.03
        if char == '�':
            return -0.45
        if char in CLOSING:
            return -0.5 if char == '}' else -0.9
        if char in '=+':
            return -0.03
        return -0.5 if char in '|#\\*/@' else -0.15
    if char.isdigit():
        if number_run > 1:
            if number_start.isalpha() or number_start == '_':
                return 0.85
            if number_start.isspace():
                return min(0.6, 0.15 * (number_run - 2))
            return 0.5
        if before.isalpha() or before == '_':
            return 1.25
        if before.isspace():
            return 0.02
        return 0.28 if before.isdigit() else 0.8
    if char.isalpha():
        if family in ('CJK', 'HIRAGANA'):
            if before.isspace():
                return -0.2
            if family == 'HIRAGANA':
                return 0.22 if len(word) <= 2 else 0.0
            return 0.35 if len(word) == 1 and before.isalnum() else 0.0
        if family in ('KATAKANA', 'HANGUL'):
            return 0.6
        if family != 'LATIN':
            return 0.8
        if before.isspace():
            return 0.5
        if before == '\\':
            return 0.0 if text in 'nrtabfv' else 0.8
        if before == '(':
            return 1.0
        if before.isdigit() or before == '_':
            return 1.6
        return 1.15 if before.isalpha() else 1.3
    if char == '�':
        return 0.3
    # Whitespace escapes and complete code delimiters close, rather than join.
    if not text.replace('\\n', '').replace('\\t', '').replace('\\r', ''):
        return 0.1
    if char in JOINING or char in OPENING:
        if '\n' in text:
            return 0.15
        return 1.2 if char in '_=^' else 0.9
    if text in ("'", '’', '“'):
        return 0.6
    if any(c.isalpha() for c in word):
        return 0.9
    return 0.08


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    text = prefix.token_strings[-1]
    run, start = 1, previous[-1:] or ' '
    if not first and text.isdigit() and previous.isdigit():
        run, start = carry[2] + 1, carry[3]
    value = predict(text, previous, first, run, start)
    return (doc, text, run, start), value

