"""layers.1.mlp.down_proj : 3892 -- the "glued word-piece" detector.

In plain terms: this component writes most strongly on a token that is stuck to the
text before it with no space in between: a piece of a longer word or identifier
(`test|bed`, `Parse`, `workspace`) or a symbol glued to code (`=`, `-`, `__`, `->`).
It is weaker on digits, on CJK characters and on closing punctuation (`.` `,` `)` `"`),
and negative on a token that starts with a space and is punctuation or a bracket
(` )`, ` :`, ` {`). It is also negative on the first token of each document. A token that
starts a new line responds less than the same token mid-line, and a digit that follows a
space or a line break does not respond at all.

The program reads only the current token, the token before it, and the document labels.
"""

import unicodedata

CLOSERS = set(".,;:)]}\"”。，、：；）」")
CJK_PREFIXES = ("CJK", "HIRAGANA", "KATAKANA", "HANGUL")
OPERATORS = set("=+-*^<>_/\\|@%&#~")

READS = ()


def is_cjk(text):
    return any(unicodedata.name(ch, "").startswith(CJK_PREFIXES) for ch in text)


def activation(text, previous, starts_document):
    """Predicted activation for token `text`, given the token before it (`previous`)."""
    if starts_document:
        return -1.0
    if text == "<|im_end|>":
        return 3.0
    if text.startswith("<|"):
        return 0.0
    core = text.strip()
    if "\n" in text or core == "":
        return 0.0
