    if lw in ("am", "pm"):
        return carry, -2.5                    # after a time stamp
    if word[-1:].isdigit():
        return carry, -0.5                    # after a date or number
    if lw in CREDIT_STRONG:
        return carry, -1.0                    # "Posted by", "Edited by"
    if lw in CREDIT_WEAK:
