expect continue begin start ask suppose seem appear remain refuse decide fail
learn choose belong lead contribute intend attempt mean refer agree manage plan
seek promise threaten offer afford'''.split())
COMPLEMENT_WORDS = set('''able unable likely unlikely going ready willing reluctant
happy pleased glad easy hard difficult important possible impossible essential
according due compared equal similar equivalent related corresponding relative
prior subject sensitive opposed close near entitled how what when where whether
is are be was were ability opportunity chance respect access addition not up
back out'''.split())
DIRECTION = set('''bring take give send return move go come transfer connect link
attach tie bind limit restrict reduce rise increase shift transition
transit put force'''.split())
# Translations of 'for', 'to', or 'in order to'; ambiguous ones have lower weights.
PURPOSE = {
    'pour': -2.6,
    'para': -2.1,
    'pra': -1.1,
    'per': -0.55,
    'чтобы': -4.9,
    'чтоб': -4.7,
    'щоб': -5.5,
    'для': -2.1,
    'để': -4.5,
    'nhằm': -2.6,
    'untuk': -2.4,
    'aby': -3.3,
    'żeby': -4.5,
    'afin': -3.3,
    'om': -1.6,
    'att': -0.85,
    'um': -1.4,
    'برای': -2.0,
}


@lru_cache(maxsize=8192)
def bases(word, pos):
    return set(wordnet.base_forms(word, pos)) | {word}


def english_to(token, previous):
    words = re.findall(r"[a-z]+(?:'[a-z]+)?", previous.lower())
    last = words[-1] if words else ''
    verbs = bases(last, 'verb')
    nouns = bases(last, 'noun')
    plain = re.sub(r'`[^`]*`', ' identifier ', previous.lower())
    clause = re.split(
        r'[.!?]\s+|\n|\\n|\b(?:to|which|that)\b', plain
    )[-1]
    recent = re.findall(r'[a-z]+', clause)[-24:]
    if not words:
        return -1.4 if token.strip() == 'To' else -0.1
    if last == 'order' and 'in' in words[-3:]:
        return -4.2
    if (last == 'use' and len(words) > 1
            and words[-2] in {'its', 'their', 'the', 'his', 'her'}):
        return 0.6
    if (last == 'used' and len(words) > 1
            and words[-2] in {'get', 'got', 'getting', 'become', 'became', 'am'}):
        return 0.6
    subjects = set("i we they he she it you i'm she's he's".split())
    if last == 'used' and len(words) > 1 and words[-2] in subjects:
        return -0.4
    if verbs & MEANS:
        return -3.2
    if last == 'needed':
        return -2.8
    if last == 'required':
        return -2.0
    if last == 'necessary':
        return -1.9
    if last == 'designed':
        return -0.9
    if last in COMPLEMENT_WORDS or verbs & COMPLEMENT_VERBS:
        return -0.05
    if 'take' in verbs and ('time' in words[-5:] or 'steps' in words[-8:]):
        return -2.4
    if last == 'thought':
        return 0.7
    if last in {'reported', 'known', 'believed', 'said', 'found'}:
        return 0.1
    if last == 'do' and any(w in {'what', 'how'} for w in words[-9:]):
        return -2.5
    if last in {'done', 'performed'}:
        return -1.8
    if last == 'bound':  # 'bound to': certainty, rather than purpose
        return 2.7
    if last == 'limited':
        return 1.5
    if verbs & {'force', 'limit', 'restrict', 'reduce', 'put', 'bind'}:
        return 1.0
    if verbs & DIRECTION:
        return 0.3
    if last == 'way':
        return 1.0
    if any(bases(w, 'verb') & MEANS for w in recent):
        return -2.7
    if nouns & INSTRUMENTS:
        return -1.5
    if last == 'steps':
        return -3.3
    if last in {'below', 'here'}:
        return -2.6
    if last in {'him', 'her', 'it', 'them', 'us', 'you', 'me'}:
        if any(bases(w, 'verb') & DIRECTION for w in words[-4:-1]):
            return 1.3
        return 0.0
    if 'from' in recent[-8:]:
        return 0.85
    if last in {'so', 'thus', 'therefore'}:
        return -2.7
    if previous.rstrip().endswith(('.', '\n', ':')):
        return -1.5
    return -1.4 if token.strip() == 'To' else -0.25


def predict(token, previous, combined):
    lower = token.strip().lower()
    # Don't mistake a suffix inside an English word for the word 'to'.
    boundary = token[:1].isspace() or not previous[-1:].isalpha()
    if lower == 'to' and boundary:
        if token.strip() == 'TO':
            return 0.0
        return english_to(token, previous)
    if (lower == 'order' and boundary
            and re.search(r'\bin\s*$', previous.lower())):
        return -4.6
    end = combined.lower()
    for word, value in PURPOSE.items():
        if end.endswith(word):
            left = end[:-len(word)]
            if left[-1:].isalpha():
                continue
            if not lower.endswith(word):  # it began in an earlier token
                return value * 1.7
            return value
    if token.strip() in {'来', '來'}:
        if previous.endswith(
                ('拿', '喜', '原', '本', '未', '向', '从', '從', '出', '回')):
            return 0.3
        means = ('用', '以', '方法', '需要', '策略', '方式',
                 '合作', '分享', '时间', '時間')
        if any(w in previous[-32:] for w in means):
            return -2.8
        return -0.4
    if token.strip() == '以':
        return -2.4 if previous.endswith(('，', '。', '；', ',')) else -0.55
    if end.endswith('เพื่'):
        return -6.8
    if lower in {'ل', 'لل'} and boundary:
        return -1.4
    if token.strip() in {'以便', '从而'}:
        return -2.2
    if token.strip() in {'用于', '才能', '即可'}:
        return -0.9
    if lower == 'so':
        return 0.04 if token.strip() == 'So' else -0.17
    if lower == 'before':
        return -0.25
    if lower == 'needed':
        return -0.55
    if lower in {'required', 'used'}:
        return -0.22
    if lower in {'me', 'us', 'him', 'her', 'them', 'you'}:
        if re.search(r'\bhelps?\s*$', previous.lower()):
            return -1.2
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    tail = b'' if fresh else carry[1]
    newest = prefix.token_bytes[-1]
    previous = tail.decode('utf-8', errors='replace')
    combined = (tail + newest).decode('utf-8', errors='replace')
    token = prefix.token_strings[-1]
    value = predict(token, previous, combined)
    if fresh and value == 0.0:
        value = -0.15
    return (doc, (tail + newest)[-720:]), value

programs.haiku:
"""Purpose 'to' detector for layers.1.mlp.down_proj component 3901.

What it does: the component is mostly silent, but on the word "to" it splits two uses.
- Purpose / means "to" (negative, strongest): "in order to", "used to", "use X to",
  "needed to", "steps to", "a tool to", "necessary to". Also the word "order" in "in order",
  sentence-initial "To" opening a purpose clause ("To do this, ..."), and the purpose
  markers of other languages ("чтобы", "để", "untuk", "pour", "para", "для", "来").
- Transfer / direction "to" (positive, weaker): "bring it to", "subject to", "limited to",
  "put to work", "taken to", "from X to Y", "on the way to", "bound to".
- Any other "to" (e.g. "want to", "went to the store") sits slightly below zero.

It reads only the last few tokens, so it is causal, and it resets at document boundaries.
"""
READS = ()

TO_WORDS = {"to", "To", "TO"}
PURPOSE_CUES = {
    "order", "use", "used", "uses", "using", "needed", "necessary", "required", "enough",
    "sufficient", "steps", "follow", "click", "below", "method", "methods", "tool", "tools",
    "script", "commands", "update", "adjust", "create", "utilized", "performed",
}
DIRECTION_CUES = {
    "way", "from", "bound", "limited", "subject", "subjected", "put", "bring", "brought",
    "bringing", "took", "taken", "take", "agree", "agreed", "directed", "connecting", "relating",
}
# Purpose markers in other languages, and their rough strength.
FOREIGN_PURPOSE = {
    "чтобы": -4.5, "để": -4.5, "untuk": -3.0, "pour": -2.5, "para": -2.0, "для": -2.0,
    "ل": -1.5, "来": -2.0,
}
SENTENCE_END = (".", "!", "?", ":", '"', "\n")


def step(carry, prefix, upstream):
    t = prefix.position
    word = prefix.token_strings[t].strip()
    same_doc_as_prev = t > 0 and prefix.document_ids[t - 1] == prefix.document_ids[t]
    prev = prefix.token_strings[t - 1].strip() if same_doc_as_prev else ""
    value = 0.0
    if word in TO_WORDS:
        if word == "To" and (prev == "" or prev.endswith(SENTENCE_END)):
            value = -2.0  # sentence-initial purpose clause
        # The last four words before this "to", within the same document.
        recent = set()
        for q in range(max(0, t - 4), t):
            if prefix.document_ids[q] == prefix.document_ids[t]:
                recent.add(prefix.token_strings[q].strip().lower())
        if recent & PURPOSE_CUES:
            value += -2.6
        elif recent & DIRECTION_CUES:
            value += 0.8
        else:
            value += -0.2
    elif word == "order" and prev.lower() == "in":
        value = -4.0  # "in order", the start of "in order to"
    elif word.lower() in FOREIGN_PURPOSE:
        value = FOREIGN_PURPOSE[word.lower()]
    return carry, value

programs.sol:
"""Sparse recognizer for document-viewer boilerplate and formatting.

Preview notices, page counters and presentation metadata get negative values.
Headings after long unfinished excerpts are treated as related-page cards.
Smaller rules cover separators, URLs, strict-mode directives and traceback/title
labels. The state is a document-local 200-character tail and a viewer flag.
Unrecognized text gets zero: this is a partial approximation, not a prose model.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        tail, previous, position, viewer = '', '', 0, False
    else:
        _, tail, previous, position, viewer = carry
    token = prefix.token_strings[-1]
    text = tail + token
    line = tail.rstrip('\n').rsplit('\n', 1)[-1]
    word = token.strip()
    lower = text.lower()
    if any(label in lower for label in (
        'start display at page:', 'more information\n', 'this preview',
        'end of the preview',
        'sunteți pe pagina',
    )):
        viewer = True

    value = 0.0
    # Page-preview notices on document-sharing sites.
    if word == 'preview' and re.search(r'\bThis preview$', text):
        value = -4.8
    elif word == 'shows' and tail.endswith('This preview'):
        value = -2.0
    elif word in ('page', 'pages') and re.search(
        r'This preview shows(?: document)? pages?$', text
    ):
        value = (-8.4 if word == 'pages' else -7.0)
        if tail.endswith(' document'):
            value = -4.4
    elif word == 'document' and tail.endswith('This preview shows'):
        value = -2.2
    elif (word in ('content', 'document', 'version')
          and tail.endswith('the full') and viewer):
        value = -2.1
    elif word == 'information' and re.search(r'(?:^|\n\n)More information$', text):
        value = -1.03
    elif word == 'of' and re.search(r'\bpage\s+\d+of$', text, re.I):
        value = -11.7
    elif word == 'din' and re.search(r'pagina\s+\d+din$', text):
        value = -10.5
    elif word == 'pagina' and 'Sunteți pe pagina' in text:
        value = -1.25
    elif word == '1' and re.search(r'(?:pagina |TEXT: )1$', text):
        value = -0.9
    elif word == '1' and viewer and re.search(r'Transcription\s+1$', text):
        value = -8.5
    # Markup / separators often left behind in extracted documents.
    elif (len(word) >= 2 and set(word) == {'·'}
          and not tail.rsplit('\n', 1)[-1].strip('· \t')):
        value = -1.97
    elif token == '\x0c':
        value = -1.2
    elif token == '\\x' and tail.endswith('\\n'):
        value = -1.0
    elif token == '###' and tail.endswith('\n\n'):
        # Headings after long, unfinished excerpts are typical related-page cards.
        cut_off = len(line) > 120 and (line[-1:].isalnum() or line.endswith(','))
        value = -0.8 if viewer else (-0.65 if cut_off else -0.10)
    elif word == 'Summary' and tail.endswith('Presentation'):
        value = -1.2
    elif word == 'presentation' and tail.endswith('Document'):
        value = -2.6
    elif text.lower().endswith('slideshare'):
        value = -3.4
    elif word.lower() == 'transcript' and tail.endswith(('###', 'Presentation')):
        value = -5.6
    elif word == 'on' and tail.endswith('Presentation'):
        value = -2.2
    elif word == 'theme' and tail.endswith('Presentation on'):
        value = -2.8
    elif token == ' "' and tail.endswith('Presentation on theme:'):
        value = -12.0
    elif viewer and word == 'Trans' and tail.endswith('\n\n'):
        value = -2.0
    elif viewer and word == 'cription' and previous == 'Trans':
        value = -3.0
    elif viewer and token == '\n\n' and tail.endswith('Transcription'):
        value = -3.0
    elif word == 'ago' and re.search(r'(?:^|\n)Views\n\d+ months ago$', text):
        value = -9.2
    elif word == 'words' and 'Pages:' in tail and re.search(r'\(\d+ words$', text):
        value = -3.2
    elif word == 'of' and re.search(r'Page\s+1 of$', text, re.I):
        value = -0.9
    elif word == 'Document' and tail.endswith('View Full'):
        value = -2.3
    elif token == '://' and re.search(r'https$', tail):
        value = 0.39
    elif word == 'strict' and re.search(r'''(?:^|\n)\s*['"]?use strict$''', text):
        value = -1.25
    elif viewer and token == '\n\n' and previous == ' information':
        value = -0.75
    # A line number in a Python stack trace, not the ordinary word "line".
    elif (token == ' line' and previous == '\",'
          and ('.py",' in tail[-10:] or 'File "' in tail)):
        value = 0.87
    elif token == ':' and re.fullmatch(r'Title:', text):
        value = 2.64
    elif token == ' .' and position == 0:
        value = -2.26
    elif token == '\r' and not tail.strip('\r'):
        value = -2.82
    elif token in ('\\n', '\\t') and not tail.replace(token, ''):
        value = -1.52 if token == '\\n' else -1.85
    elif token == '\\"' and position == 0:
        value = -2.58

    return (document, text[-200:], token, position + 1, viewer), value
